import { mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";
import process from "node:process";
import { dedent } from "@luxass/utils";

function getRequiredEnvVar(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

async function ensureDataDir() {
  const dataDir = join(process.cwd(), "src", "data");
  await mkdir(dataDir, { recursive: true });
  return dataDir;
}

const COMMENT = dedent`
  /**
   * This file is auto-generated by scripts/generate-constants.ts
   * Do not edit it manually.
   * To regenerate, run the script with:
   *  pnpm run generate:constants
   */
`;

async function run() {
  // get required environment variables
  const versions = JSON.parse(getRequiredEnvVar("UNICODE_VERSIONS"));
  const ucdVersions = JSON.parse(getRequiredEnvVar("UNICODE_UCD_VERSIONS"));
  const latestVersion = getRequiredEnvVar("UNICODE_LATEST_VERSION");
  const draftVersion = process.env.UNICODE_DRAFT_VERSION || latestVersion.replace(/\d+/, (n) => String(Number(n) + 1));

  // validate that latest version is in versions array
  const isInVersions = versions.find(({ version }) => version === latestVersion);
  if (!isInVersions) {
    throw new Error(`Latest version ${latestVersion} not found in versions array`);
  }

  // write TypeScript files with strict typing
  const dataDir = await ensureDataDir();

  // Clean up any old JSON files (migration to TypeScript)
  try {
    await unlink(join(dataDir, "unicode-version-metadata.json"));
  } catch {
    // File doesn't exist, which is fine
  }
  try {
    await unlink(join(dataDir, "ucd-path-mappings.json"));
  } catch {
    // File doesn't exist, which is fine
  }

  // generate unicode-version-metadata.ts
  const unicodeVersionMetadataContent = dedent`
    ${COMMENT}
    export const UNICODE_VERSION_METADATA = ${JSON.stringify(versions, null, 2)} as const;

    export type UnicodeVersionMetadata = typeof UNICODE_VERSION_METADATA[number];
`;

  await writeFile(
    join(dataDir, "unicode-version-metadata.ts"),
    unicodeVersionMetadataContent,
    "utf-8",
  );

  // Generate ucd-path-mappings.ts
  const ucdPathMappingsData = ucdVersions.map(({ version, mappedVersion }) => ({
    unicodeVersion: version,
    ucdPath: mappedVersion,
  }));

  const ucdPathMappingsContent = dedent`
    ${COMMENT}
    export const UCD_PATH_MAPPINGS = ${JSON.stringify(ucdPathMappingsData, null, 2)} as const;

    export type UCDPathMapping = typeof UCD_PATH_MAPPINGS[number];
`;

  await writeFile(
    join(dataDir, "ucd-path-mappings.ts"),
    ucdPathMappingsContent,
    "utf-8",
  );

  // update version numbers in constants.ts
  const constantsPath = join(process.cwd(), "src", "constants.ts");
  let content = await readFile(constantsPath, "utf-8");

  // replace the version numbers
  content = content.replace(
    /export const UNICODE_DRAFT_VERSION = "[\d.]+" as const;/,
    `export const UNICODE_DRAFT_VERSION = "${draftVersion}" as const;`,
  );
  content = content.replace(
    /export const UNICODE_STABLE_VERSION = "[\d.]+" as const;/,
    `export const UNICODE_STABLE_VERSION = "${latestVersion}" as const;`,
  );

  // write the updated constants file
  await writeFile(constantsPath, content, "utf-8");
  console.log("✅ Successfully generated TypeScript data files with strict typing!");
  console.log("📁 Created: unicode-version-metadata.ts");
  console.log("📁 Created: ucd-path-mappings.ts");
  console.log("🔢 Updated version numbers in constants.ts");
}

run().catch((error) => {
  console.error("Error updating files:", error);
  process.exit(1);
});
